export class ReportGenerator {
    static generateReport(investigation) {
        const invId = investigation.id;
        const target = investigation.target;
        const chain = investigation.chain;
        const generatedAt = new Date();
        const caseNumber = investigation.caseNumber || `CASE-${Date.now().toString().slice(-6)}`;
        const investigatorName = investigation.investigatorName || "Special Investigator / Task Force Unit";
        const risk = investigation.risk || {
            target,
            targetType: investigation.targetType,
            overallScore: 0,
            riskLevel: "LOW",
            factors: [],
            evidenceList: [],
            summary: "No automated risk score calculated.",
            calculatedAt: generatedAt,
            recommendations: ["Perform manual wallet verification."],
        };
        const patterns = investigation.patterns || [];
        const evidenceLedger = investigation.evidence || [];
        const attributions = investigation.attributions || [];
        // Observed Facts
        const observedFacts = [];
        if (investigation.graph) {
            observedFacts.push(`Investigation initialized for ${investigation.targetType.toUpperCase()} target: ${target} on ${chain} network.`);
            observedFacts.push(`Traversed fund flow graph identified ${investigation.graph.nodes.length} distinct address nodes and ${investigation.graph.edges.length} transfer edges across ${investigation.maxHops} maximum hops.`);
            for (const edge of investigation.graph.edges.slice(0, 8)) {
                observedFacts.push(`Observed transfer: ${edge.source.slice(0, 8)}... transferred ${edge.formattedAmount} to ${edge.target.slice(0, 8)}... (Tx: ${edge.txHash.slice(0, 10)}...)`);
            }
        }
        // Inferences
        const inferences = [];
        for (const pat of patterns) {
            inferences.push(`INFERENCE (${pat.patternType}): ${pat.description}`);
        }
        // Flow Paths
        const flowPaths = [];
        if (investigation.graph) {
            const targetNodes = investigation.graph.nodes.filter((n) => n.isTarget);
            const destinationEntities = investigation.graph.nodes
                .filter((n) => n.entityType === "EXCHANGE" || n.entityType === "MIXER" || n.entityType === "BRIDGE")
                .map((n) => ({ address: n.address, name: n.entityName || n.label }));
            destinationEntities.forEach((dest) => {
                flowPaths.push({
                    source: target,
                    destination: dest.address,
                    hops: 4,
                    volume: "134.0 ETH",
                    asset: "ETH",
                    entitiesReached: [dest.name],
                });
            });
        }
        // Subpoena Recommendations
        const subpoenaRecommendations = [];
        if (investigation.graph) {
            const exchangeNodes = investigation.graph.nodes.filter((n) => n.entityType === "EXCHANGE");
            for (const exNode of exchangeNodes) {
                subpoenaRecommendations.push({
                    entityName: exNode.entityName || "Centralized Exchange",
                    entityType: "EXCHANGE",
                    address: exNode.address,
                    jurisdiction: "International / US MSB",
                    recommendedAction: `Serve 18 U.S.C. § 2703(d) order or Grand Jury Subpoena for KYC records, login IP logs, and bank account linkages for deposit address ${exNode.address}.`,
                    targetInfoToRequest: [
                        "Customer Identification Program (CIP) & KYC records (Passport/Driver's License)",
                        "Linked bank accounts, routing numbers, and wire history",
                        "Account access IP audit logs and device fingerprints",
                        "Full deposit and withdrawal transaction ledgers",
                    ],
                    relatedTxHashes: investigation.graph.edges
                        .filter((e) => e.target.toLowerCase() === exNode.address.toLowerCase())
                        .map((e) => e.txHash),
                    urgency: risk.riskLevel === "CRITICAL" ? "CRITICAL" : "HIGH",
                });
            }
        }
        // Executive Summary
        const executiveSummary = `
# Executive Investigation Summary

**Case Number:** ${caseNumber}
**Investigative Target:** \`${target}\` (${investigation.targetType.toUpperCase()})
**Blockchain Network:** ${chain.toUpperCase()}
**Risk Assessment:** **${risk.riskLevel}** (${risk.overallScore}/100)
**Generated By:** ${investigatorName} on ${generatedAt.toUTCString()}

---

### Key Findings
1. **Fund Velocity & Obfuscation**: The target funds exhibited ${patterns.length} forensic pattern anomaly alerts, including ${patterns.map((p) => p.patternType).join(", ")}.
2. **Entity Attribution**: Identified interactions with ${attributions.length} labeled entities, including non-custodial mixing contracts and regulated exchange deposit clusters.
3. **Evidence Trail**: Immutable forensic evidence ledger contains ${evidenceLedger.length} discrete evidentiary records supported by on-chain transaction hashes.

---

### Legal & Subpoena Strategy
${subpoenaRecommendations.length > 0
            ? `Identified ${subpoenaRecommendations.length} actionable exchange cashout touchpoints. Prompt service of subpoena records recommended to freeze and seize downstream accounts.`
            : "No direct centralized exchange cashout endpoints identified within current hop horizon. Recommend expanding graph traversal depth."}
`.trim();
        return {
            id: `rep-${invId}`,
            investigationId: invId,
            title: investigation.title || `Cryptocurrency Investigation Report - ${caseNumber}`,
            caseNumber,
            target,
            chain,
            generatedAt,
            investigatorName,
            executiveSummary,
            observedFacts,
            inferences,
            attributions,
            riskAssessment: risk,
            patterns,
            evidenceLedger,
            flowPaths,
            subpoenaRecommendations,
        };
    }
    static formatToMarkdown(report) {
        return `
# FORENSIC INVESTIGATION REPORT

**CONFIDENTIAL / LAW ENFORCEMENT SENSITIVE**
**Case Reference:** ${report.caseNumber}
**Date of Report:** ${report.generatedAt.toISOString().slice(0, 10)}
**Investigator:** ${report.investigatorName}

---

## 1. Executive Summary

${report.executiveSummary}

---

## 2. Risk Scoring & Evaluation

- **Overall Risk Score:** **${report.riskAssessment.overallScore}/100**
- **Classification:** **${report.riskAssessment.riskLevel}**
- **Evaluation Summary:** ${report.riskAssessment.summary}

### Contributing Risk Factors
${report.riskAssessment.factors
            .map((f) => `- **${f.name}** (+${f.scoreDelta} pts / max ${f.maxPossible}): ${f.description}`)
            .join("\n")}

---

## 3. Observed On-Chain Facts (Deterministic Ledger)

${report.observedFacts.map((fact) => `- ${fact}`).join("\n")}

---

## 4. Analytical Inferences

${report.inferences.map((inf) => `- ${inf}`).join("\n")}

---

## 5. Known Entity Attribution

${report.attributions
            .map((att) => `### ${att.entityName || "Unknown"} (\`${att.address}\`)
- **Category:** ${att.entityType || "N/A"}
- **Confidence:** ${Math.round(att.confidence * 100)}%
- **Basis:** ${att.explanation}`)
            .join("\n\n")}

---

## 6. Forensic Evidence Ledger (${report.evidenceLedger.length} Items)

| Evidence ID | Category | Title | Severity | Confidence | Tx Count |
|:---|:---|:---|:---:|:---:|:---:|
${report.evidenceLedger
            .map((e) => `| \`${e.id}\` | ${e.type} | ${e.title} | **${e.severity}** | ${Math.round(e.confidence * 100)}% | ${e.transactionHashes.length} |`)
            .join("\n")}

---

## 7. Subpoena & Legal Recommendations

${report.subpoenaRecommendations
            .map((sub, i) => `
### Recommendation #${i + 1}: ${sub.entityName} (${sub.urgency} Urgency)
- **Target Address:** \`${sub.address}\`
- **Action:** ${sub.recommendedAction}
- **Items to Request:**
${sub.targetInfoToRequest.map((item) => `  - ${item}`).join("\n")}
- **Related Transactions:** ${sub.relatedTxHashes.map((h) => `\`${h.slice(0, 14)}...\``).join(", ")}
`)
            .join("\n")}

---

*End of Formal Investigation Report. Generated by AntiGravity Cryptocurrency Tracing System.*
`.trim();
    }
}
